create table if not exists public.pixel_orders (id uuid primary key default gen_random_uuid(), stripe_session_id text unique, stripe_payment_intent_id text, x integer not null check (x between 0 and 49), y integer not null check (y between 0 and 49), color text not null check (color ~ '^#[0-9A-Fa-f]{6}$'), display_text text, country_flag text, social_link text, amount_gbp_pence integer not null check (amount_gbp_pence > 0), status text not null default 'pending' check (status in ('pending','paid','failed','expired','cancelled')), created_at timestamptz not null default now(), paid_at timestamptz, expires_at timestamptz not null default now()+interval '30 minutes');
create table if not exists public.pixel_reservations (x integer not null check (x between 0 and 49), y integer not null check (y between 0 and 49), order_id uuid primary key references public.pixel_orders(id) on delete cascade, expires_at timestamptz not null, created_at timestamptz not null default now(), unique(x,y));
alter table public.pixel_orders enable row level security;
alter table public.pixel_reservations enable row level security;
revoke all on public.pixel_orders from anon, authenticated;
revoke all on public.pixel_reservations from anon, authenticated;
create unique index if not exists pixels_xy_unique on public."Pixels"(x,y);
create or replace function public.pixel_price(p_x integer,p_y integer) returns integer language sql immutable as $$ select case when sqrt((p_x-25)^2+(p_y-25)^2) < 5 then 299 when sqrt((p_x-25)^2+(p_y-25)^2) < 15 then 199 when sqrt((p_x-25)^2+(p_y-25)^2) < 25 then 99 else 49 end $$;
create or replace function public.reserve_pixel(p_x integer,p_y integer,p_color text,p_display_text text,p_country_flag text,p_social_link text) returns table(order_id uuid, amount_gbp_pence integer) language plpgsql security definer set search_path=public as $$ declare v_order uuid; v_amount integer; begin if p_x<0 or p_x>49 or p_y<0 or p_y>49 then raise exception 'Invalid coordinates'; end if; if p_color !~ '^#[0-9A-Fa-f]{6}$' then raise exception 'Invalid color'; end if; if p_display_text is not null and char_length(p_display_text)>30 then raise exception 'Display text too long'; end if; if p_country_flag is not null and char_length(p_country_flag)>20 then raise exception 'Invalid country'; end if; if p_social_link is not null and char_length(p_social_link)>2048 then raise exception 'Social link too long'; end if; if exists(select 1 from public."Pixels" where x=p_x and y=p_y) then raise exception 'Pixel already claimed'; end if; v_amount:=public.pixel_price(p_x,p_y); insert into public.pixel_orders(x,y,color,display_text,country_flag,social_link,amount_gbp_pence) values(p_x,p_y,p_color,coalesce(nullif(p_display_text,''),'Anonymous'),coalesce(nullif(p_country_flag,''),'global'),p_social_link,v_amount) returning id into v_order; insert into public.pixel_reservations(x,y,order_id,expires_at) values(p_x,p_y,v_order,now()+interval '30 minutes'); return query select v_order,v_amount; exception when unique_violation then raise exception 'Pixel is currently reserved'; end $$;
revoke all on function public.reserve_pixel(integer,integer,text,text,text,text) from public,anon,authenticated;
grant execute on function public.reserve_pixel(integer,integer,text,text,text,text) to service_role;
